def _normalize_parent(work_id, parent, card_type) -> str:
    if card_type == "剧本":
        return ""
    wid = work_store.work_card_id_of(work_id)
    if parent is None or parent == "":
        return wid            # ← wid 即本剧本的根卡 id
    if not _card_path(work_id, parent).exists():
        return wid
    return parent
